arguments.command:
$(cat graphify-out/.graphify_python) - << 'EOF'
import json, os
from pathlib import Path
from collections import defaultdict

chunks = []
uncached = Path('graphify-out/.graphify_uncached.txt').read_text(encoding='utf-8').splitlines()
detect = json.loads(Path('graphify-out/.graphify_detect.json').read_text(encoding='utf-8'))
images = set(detect.get('files', {}).get('image', []))
for img in images:
    if img in uncached:
        chunks.append([img])
others = [f for f in uncached if f not in images]
groups = defaultdict(list)
for f in others:
    groups[os.path.dirname(f) or '(root)'].append(f)
ordered = list(groups.values())
chunk_size = 22
current = []
for group in ordered:
    if len(current) + len(group) <= chunk_size:
        current.extend(group)
    else:
        if current:
            chunks.append(current)
        if len(group) > chunk_size:
            for i in range(0, len(group), chunk_size):
                chunks.append(group[i:i+chunk_size])
            current = []
        else:
            current = group.copy()
if current:
    chunks.append(current)
Path('graphify-out/.graphify_chunks.json').write_text(json.dumps(chunks, ensure_ascii=False), encoding='utf-8')
print(f'Chunks: {len(chunks)}')
EOF

